SET DEFINE OFF;
WHENEVER SQLERROR EXIT FAILURE;

MERGE INTO CARD_MASTER t
USING (
    SELECT 2022 cid, 22 uid, 2002 aid, '9400-0022-0000-0001' cnum FROM DUAL
) s ON (t.CARD_ID = s.cid)
WHEN NOT MATCHED THEN
    INSERT (CARD_ID, USER_ID, LINKED_ACCOUNT_ID, CARD_NUMBER, CARD_STATUS)
    VALUES (s.cid, s.uid, s.aid, s.cnum, 'ACTIVE');

